content.content:
# A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet ({"to": <person id>}). Responds with the sheet's claims.
validate:
  class: net.officefloor.hq.app.claim.ValidateReassign
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: reassign
reassign:
  class: net.officefloor.hq.app.claim.ReassignClaim
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
# Defer an OPEN claim outside a closed period until a date after the sheet's today ({"until": "yyyy-MM-dd"}). Responds with the sheet's claims.
validate:
  class: net.officefloor.hq.app.claim.ValidateDefer
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: defer
defer:
  class: net.officefloor.hq.app.claim.DeferClaim
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
# Change a claim's status: {change} is open, settle, void, approve or reject (with {"reason"} in the body). Responds with the sheet's claims.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheet}/claims/{claim}/reassign: the id of the person the claim moves to. */
public record ReassignRequest(Long to) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the reassign body once, refusing one that names no person. */
public class ValidateReassign {
    public void validate(@RequestBody ReassignRequest request, Out<ReassignRequest> body)
            throws InvalidClaimStatusChangeException {
        if (request == null || request.to() == null) {
            throw new InvalidClaimStatusChangeException("A reassign names the person the claim moves to");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Moves a DRAFT, OPEN or PENDING claim to another person on the sheet; only a role the permission matrix lets (by default a steward) may. The claim keeps its number
 * and date, loses any figure a statement bound it to, and lists as its new person's newest claim.
 */
public class ReassignClaim {
    public void reassign(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val ReassignRequest body, @Val Claim claim, Claims claims, People people, Roles roles, Settings settings, Audit audit,
            Rollup rollup) throws InvalidClaimStatusChangeException {
        if (!settings.permits(sheet, "reassign", roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Your role may not reassign a claim");
        }
        if (claim.status() != ClaimStatus.DRAFT && claim.status() != ClaimStatus.OPEN
                && claim.status() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be reassigned");
        }
        Person from = people.find(sheet, claim.person());
        Person to = people.find(sheet, body.to());
        if (to == null || to.id() == claim.person()) {
            throw new InvalidClaimStatusChangeException("A claim is reassigned to another person on the sheet");
        }
        Rollup.Snapshot before = rollup.take(sheet);
        // Conditional on the person and status read, so a concurrent change by another user is refused, not overwritten.
        if (!claims.reassign(sheet, claim.id(), claim.person(), claim.status(), to.id())) {
            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
        }
        audit.record("CLAIM_REASSIGNED sheet=" + sheet + " by=" + user + " " + claim.statusAuditFields(to.name())
                + " from=" + from.name() + " to=" + to.name());
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
