1	import { useState } from 'react';
2	import type { FormEvent } from 'react';
3	import { useMutation, useQueryClient } from '@tanstack/react-query';
4	import { postJson, putJson } from '../../api/http';
5	import { useSubmitOnce } from '../../query/useSubmitOnce';
6	import { byUser } from '../session/session';
7	import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
8	import { gradeOn, peoplePath, usePeople } from '../people/people';
9	import type { Grade, Person } from '../people/people';
10	import { useSheetToday } from '../sheet/sheet';
11	import { rateOf, showDue, twoDecimals, useRates } from '../rates/rates';
12	import type { Rate } from '../rates/rates';
13	import { periodOf, usePeriods } from '../periods/periods';
14	import { useCapCents, useFloorCents } from '../settings/settings';
15	import {
16	  claimDueCents,
17	  claimed,
18	  claimsKey,
19	  claimsPath,
20	  counted,
21	  overdue,
22	  overdueCents,
23	  personDueCents,
24	  uncappedPersonDueCents,
25	  useClaims,
26	  useLate,
27	} from './claims';
28	import type { Claim, ClaimStatusChange } from './claims';
29	import { selectClaim, useSelectedClaims } from './selection';
30	
31	type Draft = { amount: string; date: string; note: string; corrects: string };
32	const EMPTY: Draft = { amount: '', date: '', note: '', corrects: '' };
33	
34	function ClaimedHeader() {
35	  return (
36	    <>
37	      <th>Claimed</th>
38	      <th>Due total</th>
39	      <th>Excess</th>
40	      <th>Overdue</th>
41	      <th>Overdue total</th>
42	      <th>Claims</th>
43	    </>
44	  );
45	}
46	
47	const CHANGES: { change: ClaimStatusChange; label: string }[] = [
48	  { change: 'open', label: 'Open' },
49	  { change: 'settle', label: 'Settle' },
50	  { change: 'void', label: 'Void' },
51	  { change: 'approve', label: 'Approve' },
52	];
53	
54	// One claim with its status and the buttons that change it. Every button is offered; the server
55	// refuses a change the claim's status does not allow, and the row shows that error until its next action.
56	function ClaimRow({ sheet, user, claim, rates, grade, editing, onEdit, onCancel }: {
57	  sheet: string;
58	  user: string;
59	  claim: Claim;
60	  rates: Rate[];
61	  grade: Grade | undefined;
62	  editing: boolean;
63	  onEdit: () => void;
64	  onCancel: () => void;
65	}) {
66	  const queryClient = useQueryClient();
67	  const { data: periods = [] } = usePeriods(sheet);
68	  const floor = useFloorCents(sheet);
69	  const today = useSheetToday(sheet);
70	  const late = useLate(sheet);
71	  const status = useMutation({
72	    mutationFn: (change: ClaimStatusChange) =>
73	      postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}/${change}`, user), change === 'reject' ? { reason } : {}),
74	    onSuccess: (updated) => queryClient.setQueryData(claimsKey(sheet), updated),
75	  });
76	
77	  const act = useSubmitOnce(status);
78	  // A role the permission matrix lets (by default a steward) moves a DRAFT, OPEN or PENDING claim to another person on the sheet, picked beside the Reassign button.
79	  const { data: people = [] } = usePeople(sheet);
80	  const [moveTo, setMoveTo] = useState('');
81	  const move = useMutation({
82	    mutationFn: (to: number) =>
83	      postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}/reassign`, user), { to }),
84	    onSuccess: (updated) => {
85	      setMoveTo('');
86	      queryClient.setQueryData(claimsKey(sheet), updated);
87	    },
88	  });
89	  const reassign = useSubmitOnce(move);
90	  // A steward re-settles a SETTLED claim: its due is fixed again at today's live figure.
91	  const resettleMutation = useMutation({
92	    mutationFn: () => postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}/resettle`, user), {}),
93	    onSuccess: (updated) => queryClient.setQueryData(claimsKey(sheet), updated),
94	  });
95	  const resettle = useSubmitOnce(resettleMutation);
96	  // An OPEN claim is deferred to a date after the sheet's today, typed beside the Defer button.
